used=set(l.strip().lower() for l in open('/home/claude/hunter/used_domains_all.txt') if l.strip())
from collections import Counter
emails=[o["email"].lower() for o in out]
assert len(emails)==len(set(emails)), "dup emails"
c=Counter(o["domain"] for o in out)
assert max(c.values())<=5, c
for o in out:
    assert o["domain"] not in used, o
    assert o["verification"] in ("valid","accept_all"), o
    assert o["email"].lower().split("@")[1]==o["domain"], o
    assert o["type"] in ("personal","generic")
